<?php require_once __DIR__.'/../includes/student_auth_check.php';require_once __DIR__.'/../config/db.php';$status=$_GET['status']??'';$rows=[];try{$p=db();$sql='SELECT b.*,s.name subject,u.full_name tutor FROM bookings b JOIN subjects s ON s.id=b.subject_id JOIN tutors t ON t.id=b.tutor_id JOIN users u ON u.id=t.user_id WHERE b.student_id=:id';$args=['id'=>$_SESSION['user_id']];if(in_array($status,['pending','accepted','completed','cancelled','rejected'],true)){$sql.=' AND b.status=:status';$args['status']=$status;}$sql.=' ORDER BY b.booking_date DESC';$q=$p->prepare($sql);$q->execute($args);$rows=$q->fetchAll();}catch(Throwable $e){}$pageTitle='My bookings';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';?><main class="container py-5"><h1 class="h2">My bookings</h1><form class="mb-3"><select class="form-select w-auto" name="status" onchange="this.form.submit()"><option value="">All statuses</option><?php foreach(['pending','accepted','completed','cancelled','rejected'] as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></form><div class="table-responsive"><table class="table"><tr><th>Tutor</th><th>Subject</th><th>Date</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['tutor'])?></td><td><?=e($r['subject'])?></td><td><?=e($r['booking_date'])?></td><td><span class="badge text-bg-secondary"><?=e($r['status'])?></span></td></tr><?php endforeach;?></table></div></main><?php require __DIR__.'/../includes/footer.php';?>
